class C_API_Resource { /* Opaque C-style resource */ };
C_API_Resource* acquire_resource() { return new C_API_Resource(); }
void release_resource(C_API_Resource* res) { delete res; /* Custom release logic */ }

// A custom deleter for the C-style resource.
// It's a stateless function object (functor).
struct ResourceDeleter {
    void operator()(C_API_Resource* res) const {
        std::cout << "Custom deleter called!\n";
        release_resource(res);
    }
};

// A logging deleter implemented as a lambda.
auto loggingDeleter = [](C_API_Resource* res) {
    std::cout << "Logging and then deleting resource.\n";
    release_resource(res);
};

int main() {
    // Using a function object as a custom deleter.
    // The deleter's type is part of the unique_ptr's type.
    std::unique_ptr<C_API_Resource, ResourceDeleter> p1(acquire_resource());

    // Using a lambda as a custom deleter.
    // The type is inferred using decltype.
    std::unique_ptr<C_API_Resource, decltype(loggingDeleter)> 
        p2(acquire_resource(), loggingDeleter);

    // std::unique_ptr<C_API_Resource> p3 = std::move(p1); // COMPILE ERROR!
    // The types are different: std::unique_ptr<C_API_Resource, ResourceDeleter>
    // is not convertible to std::unique_ptr<C_API_Resource, std::default_delete<...>>

} // p1 and p2 are destroyed here, invoking their respective custom deleters.
